create table public.estate_properties (
 id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
 category text not null, published boolean not null default false, featured boolean not null default false,
 sort_order integer not null default 0, image text not null, images jsonb not null default '[]', documents jsonb not null default '[]',
 content_fr jsonb not null, content_en jsonb not null,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.estate_visit_requests (
 id uuid primary key default gen_random_uuid(), submission_id uuid not null unique,
 property_id text references public.estate_properties(id) on delete set null,
 property_slug text not null, property_title text not null, property_location text not null, property_type text not null,
 first_name text not null, last_name text not null default '', email text not null, phone text not null, locale text not null check(locale in ('fr','en')),
 status text not null default 'new' check(status in ('new','contacted','valuation','mandate','closed','lost')),
 notes text not null default '', next_follow_up date,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index estate_visits_created on public.estate_visit_requests(created_at desc,id);
create index estate_visits_property on public.estate_visit_requests(property_id);
create table public.estate_rate_limits (key text primary key, window_start timestamptz not null, attempts integer not null);
alter table public.estate_properties enable row level security;
alter table public.estate_visit_requests enable row level security;
alter table public.estate_rate_limits enable row level security;
revoke all on public.estate_properties, public.estate_visit_requests, public.estate_rate_limits from anon, authenticated;
grant all on public.estate_properties, public.estate_visit_requests, public.estate_rate_limits to service_role;
create function public.estate_allow_request(rate_key text, max_attempts integer, window_seconds integer)
returns boolean language plpgsql security invoker set search_path = '' as $$
declare count_now integer;
begin
 delete from public.estate_rate_limits where window_start < now() - interval '1 day';
 insert into public.estate_rate_limits as r(key,window_start,attempts) values(rate_key,now(),1)
 on conflict(key) do update set
 attempts = case when r.window_start < now()-make_interval(secs=>window_seconds) then 1 else r.attempts+1 end,
 window_start = case when r.window_start < now()-make_interval(secs=>window_seconds) then now() else r.window_start end
 returning attempts into count_now;
 return count_now <= max_attempts;
end; $$;
revoke all on function public.estate_allow_request(text,integer,integer) from public, anon, authenticated;
grant execute on function public.estate_allow_request(text,integer,integer) to service_role;

